package core

import (
	"crypto/ed25519"
	"encoding/hex"
	"fmt"
	"time"
)

// ExtractionReceipt represents a signed receipt generated by the residential node upon job completion.
type ExtractionReceipt struct {
	TaskID       uint64  `json:"task_id"`
	WorkerID     string  `json:"worker_id"`
	URL          string  `json:"url"`
	StatusCode   int     `json:"status_code"`
	ResultBytes  int     `json:"result_bytes"`
	PriceCredits float64 `json:"price_credits"`
	Timestamp    int64   `json:"timestamp"`
	Signature    string  `json:"signature"`
}

// GenerateExtractionReceipt signs proof that the residential worker extracted the target URL
func GenerateExtractionReceipt(taskID uint64, workerID, targetURL string, statusCode int, resultBytes int, priceCredits float64, privKeyHex string) (*ExtractionReceipt, error) {
	if privKeyHex == "" {
		return nil, fmt.Errorf("missing private key for receipt signing")
	}

	privKeyBytes, err := hex.DecodeString(privKeyHex)
	if err != nil || len(privKeyBytes) != 64 {
		return nil, fmt.Errorf("invalid private key: %v", err)
	}
	privKey := ed25519.PrivateKey(privKeyBytes)

	now := time.Now().Unix()
	receipt := &ExtractionReceipt{
		TaskID:       taskID,
		WorkerID:     workerID,
		URL:          targetURL,
		StatusCode:   statusCode,
		ResultBytes:  resultBytes,
		PriceCredits: priceCredits,
		Timestamp:    now,
	}

	dataToSign := []byte(fmt.Sprintf("%d:%s:%s:%d:%d:%f:%d",
		receipt.TaskID, receipt.WorkerID, receipt.URL, receipt.StatusCode, receipt.ResultBytes, receipt.PriceCredits, receipt.Timestamp))

	sig := ed25519.Sign(privKey, dataToSign)
	receipt.Signature = hex.EncodeToString(sig)

	return receipt, nil
}

// VerifyExtractionReceipt verifies that the receipt was signed by the worker's public key
func VerifyExtractionReceipt(receipt *ExtractionReceipt, pubKeyHex string) (bool, error) {
	if pubKeyHex == "" {
		return false, fmt.Errorf("missing public key for verification")
	}

	pubKeyBytes, err := hex.DecodeString(pubKeyHex)
	if err != nil || len(pubKeyBytes) != 32 {
		return false, fmt.Errorf("invalid public key: %v", err)
	}
	pubKey := ed25519.PublicKey(pubKeyBytes)

	dataToSign := []byte(fmt.Sprintf("%d:%s:%s:%d:%d:%f:%d",
		receipt.TaskID, receipt.WorkerID, receipt.URL, receipt.StatusCode, receipt.ResultBytes, receipt.PriceCredits, receipt.Timestamp))

	sigBytes, err := hex.DecodeString(receipt.Signature)
	if err != nil {
		return false, fmt.Errorf("invalid signature hex: %v", err)
	}

	return ed25519.Verify(pubKey, dataToSign, sigBytes), nil
}

// SimulatedBillingLedger wraps SQLite queries to preserve balance tracking
type SimulatedBillingLedger struct{}

func LoadLedger() (*SimulatedBillingLedger, error) {
	err := InitDB()
	if err != nil {
		return nil, err
	}
	return &SimulatedBillingLedger{}, nil
}

func (l *SimulatedBillingLedger) GetBalance(id string) float64 {
	return GetBalanceDB(id)
}

func (l *SimulatedBillingLedger) SetBalance(id string, amount float64) {
	_ = SetBalanceDB(id, amount)
}

func (l *SimulatedBillingLedger) Save() error {
	return nil
}
